CREATE OR ALTER PROCEDURE [dbo].[uspOrderReconciliation_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @OrderId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @ProofOfDeliveryId UNIQUEIDENTIFIER = NULL
	, @ReconciliationDate DATETIME2 = NULL
	, @OrderedQuantity DECIMAL(18,4) = NULL
	, @DeliveredQuantity DECIMAL(18,4) = NULL
	, @AcceptedQuantity DECIMAL(18,4) = NULL
	, @FinalAmount DECIMAL(18,4) = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[OrderId]
			, t.[ProducedQty]
			, t.[PackedQty]
			, t.[VarianceQty]
			, t.[VariancePercent]
			, t.[Status]
			, t.[Remark]
			, t.[ProofOfDeliveryId]
			, t.[ReconciliationDate]
			, t.[OrderedQuantity]
			, t.[DeliveredQuantity]
			, t.[AcceptedQuantity]
			, t.[FinalAmount]
			, t.[Note]
			, t.[CreatedDate]
		FROM [dbo].[OrderReconciliation] AS t
		
		WHERE 1 = 1
			AND (@OrderId IS NULL OR t.[OrderId] = @OrderId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@ProofOfDeliveryId IS NULL OR t.[ProofOfDeliveryId] = @ProofOfDeliveryId)
			AND (@ReconciliationDate IS NULL OR t.[ReconciliationDate] = @ReconciliationDate)
			AND (@OrderedQuantity IS NULL OR t.[OrderedQuantity] = @OrderedQuantity)
			AND (@DeliveredQuantity IS NULL OR t.[DeliveredQuantity] = @DeliveredQuantity)
			AND (@AcceptedQuantity IS NULL OR t.[AcceptedQuantity] = @AcceptedQuantity)
			AND (@FinalAmount IS NULL OR t.[FinalAmount] = @FinalAmount)
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'orderId' THEN r.[OrderId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'orderId' THEN r.[OrderId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'producedQty' THEN r.[ProducedQty] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'producedQty' THEN r.[ProducedQty] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'packedQty' THEN r.[PackedQty] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'packedQty' THEN r.[PackedQty] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'varianceQty' THEN r.[VarianceQty] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'varianceQty' THEN r.[VarianceQty] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'variancePercent' THEN r.[VariancePercent] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'variancePercent' THEN r.[VariancePercent] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'remark' THEN r.[Remark] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'remark' THEN r.[Remark] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'proofOfDeliveryId' THEN r.[ProofOfDeliveryId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'proofOfDeliveryId' THEN r.[ProofOfDeliveryId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'reconciliationDate' THEN r.[ReconciliationDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'reconciliationDate' THEN r.[ReconciliationDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'orderedQuantity' THEN r.[OrderedQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'orderedQuantity' THEN r.[OrderedQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveredQuantity' THEN r.[DeliveredQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveredQuantity' THEN r.[DeliveredQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'acceptedQuantity' THEN r.[AcceptedQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'acceptedQuantity' THEN r.[AcceptedQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'finalAmount' THEN r.[FinalAmount] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'finalAmount' THEN r.[FinalAmount] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
